import{z as d,x as E,o as r,c as A,q as l,j as n,D as i,d as e,s as o,S as p,b as t}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"虚表与动态分派","description":"","frontmatter":{"title":"虚表与动态分派","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/vtable-dispatch.md","filePath":"cs/vtable-dispatch.md","lastUpdated":1791413859000}'),B={name:"cs/vtable-dispatch.md"};function h(c,a,u,m,C,f){const s=E("Mermaid");return r(),A("div",null,[a[2]||(a[2]=l('<h1 id="虚表与动态分派" tabindex="-1">虚表与动态分派 <a class="header-anchor" href="#虚表与动态分派" aria-label="Permalink to &quot;虚表与动态分派&quot;">​</a></h1><div class="epigraph"><p>对象头指向方法表；调用 `p-&gt;f()` 变成 `p-&gt;vptr[i](p)`。单继承表简单，多继承与接口要 thunk 或 Itanium 式偏移。</p><footer>—— 据 Ellis and Stroustrup, The Annotated C++ Reference Manual；Itanium C++ ABI；对照[内联缓存](/cs/inline-caching) 与[类型类](/cs/typeclass-dictionary) 整理</footer></div><p>上一课<a href="/cs/trampolining">蹦床</a>是函数式一侧的控制流。本课转到 OOP 的动态分派：缺口是 <strong>vtable</strong> 的布局——调用 <code>p-&gt;f()</code> 如何变成查表跳转。反射留下一课。主干类型课讲过编译期的 overload；这里是运行时的表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态重载在编译期按静态类型选定；虚函数要看接收者的运行时类型。C++ 式实现：每类一张表，虚方法按声明序占槽，对象头藏一个 vptr 指向本类表，<code>p-&gt;f()</code> 编译成 <code>p-&gt;vptr[i](p)</code>。缺口是两件事：槽位索引的兼容（子类沿用父类槽位），与 this 指针的调整；IC 状态机是动态语言的事，不在本课。单继承最简单：子类表是父类表的前缀兼容扩展。多继承：对象里有多个子对象、多个 vptr，经第二个基类的指针调用时 this 要从对象头平移到对应子对象，编译器放一个 thunk 先调指针再跳方法。接口调用：另起一张接口表或 Itanium 式间接表。</p><h3 id="虚表不是类型类字典的复制粘贴" tabindex="-1">虚表不是类型类字典的复制粘贴 <a class="header-anchor" href="#虚表不是类型类字典的复制粘贴" aria-label="Permalink to &quot;虚表不是类型类字典的复制粘贴&quot;">​</a></h3><p>与<a href="/cs/typeclass-dictionary">类型类</a>对照：字典通常在调用处构造传递，静态可知；vtable 挂在对象上，为的是支持编译期未知的新子类——开放世界。IC（内联缓存）则把虚调用投机成直跳，靠观察到的类型分布赌一把。</p><p><span class="marginnote">ARM C++ / Itanium ABI。Stroustrup。本课 C++ 模型；Java 接口表类似。不写 COM 全部。</span></p><p><span class="marginnote">「thunk」翻译成大白话：编译器悄悄塞进调用路径的一段小垫片。它不做业务逻辑，只干一件事——把 this 指针从子对象位置平移回对象头，让方法体以为自己收到的是完整对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>前端三件事：每个虚方法分一个槽位，构造函数写 vptr，调用点编译成取表加间接跳。优化侧叫去虚：类层次分析（CHA）证明只有一个实现，或运行时已知具体类型，就直调甚至内联。JIT 用 CHA 必须记录依赖——赌了「没有别的子类」——类加载破坏假设时回退去优化。</p>',11)),(r(),n(p,null,{default:i(()=>[o(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBJ%5B%22%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20VP%5B%22vptr%22%5D%0A%20%20VP%20--%3E%20SLOT%5B%22%E6%A7%BD%20i%22%5D%0A%20%20SLOT%20--%3E%20F%5B%22%E6%96%B9%E6%B3%95%20%2B%20this%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,[t("span",{class:"marginnote"},"数字实例：64 位机器上单继承对象只要 8 字节存一个 vptr；虚表本身每类一份、与对象个数无关——一百万个对象也共享同一张表。初学者容易以为每个对象都背着自己的方法表，实际上背的只是一个指向表的指针。")],-1)),a[4]||(a[4]=t("p",null,[e("与"),t("a",{href:"/cs/calling-convention-impl"},"调用约定"),e("衔接：this 是隐式第一参数，thunk 改的就是它。与 GC 的交界：vptr 不是用户字段，但 GC 扫对象要认得它，让它跟着对象搬移。")],-1)),a[5]||(a[5]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=t("p",null,"多重继承的菱形再加虚基类，偏移要查运行期结构，复杂度再上一档。工程红线：不要手填 vptr 当「安全加固」——伪造或篡改 vptr 正是漏洞利用的常见跳板。Swift/Rust 的 trait 对象是另一布局：胖指针 {data, vtable} 把表从对象头挪进指针，对象不再背表——正对照类型类字典的位置选择。",-1)),(r(),n(p,null,{default:i(()=>[o(s,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20PTR%5B%22%E6%8C%87%E9%92%88%E6%8C%87%E5%90%91%E7%AC%AC%E4%BA%8C%E4%B8%AA%E5%9F%BA%E7%B1%BB%E5%AD%90%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20THUNK%5B%22%E5%85%88%E6%89%A7%E8%A1%8C%20thunk%22%5D%0A%20%20THUNK%20--%3E%20ADJ%5B%22this%20%E5%B9%B3%E7%A7%BB%E5%9B%9E%E5%AF%B9%E8%B1%A1%E5%A4%B4%22%5D%0A%20%20ADJ%20--%3E%20MVT%5B%22%E6%8C%89%E8%AF%A5%E5%9F%BA%E7%B1%BB%E8%87%AA%E5%B7%B1%E7%9A%84%20vtable%20%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20MVT%20--%3E%20MSLOT%5B%22%E5%8F%96%E5%87%BA%E6%96%B9%E6%B3%95%E6%A7%BD%E4%B8%8E%E4%BF%AE%E6%AD%A3%E5%90%8E%E7%9A%84%20this%22%5D%0A%20%20MSLOT%20--%3E%20JUMP%5B%22%E8%B7%B3%E8%BD%AC%E6%89%A7%E8%A1%8C%E6%96%B9%E6%B3%95%E4%BD%93%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p><span class="marginnote">常见误区：以为 JIT 用类层次分析（CHA）去虚后就一劳永逸。CHA 赌的是「没有别的子类」——运行时一旦加载新子类，所有依赖该假设的直调与内联都要回退重编，这正是去优化机制存在的理由。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写反射。后课默认：开放世界的方法分派用 vtable，闭世界可整体静态化。下一课反射与元数据。</p><p>也不把虚表类比成数据库视图——它是代码布局，不是数据抽象。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>虚调用 = 对象 vptr 查表取槽，this 作隐式参数。</li><li>多继承跨基类调用要偏移 thunk 调整 this。</li><li>去虚与 IC 把动态分派压回静态调用。</li><li>出处：Itanium C++ ABI；Ellis and Stroustrup；对照 Hölzle IC。</li></ul>',6))])}const b=d(B,[["render",h]]);export{T as __pageData,b as default};
